// The authored-source citation seam used by both the `.mdx` Vite source plugin
// and the `.md` Markdown processor: content-dir scoping (including symlinked
// roots), the `hasCitation` short-circuit, resolution to logical routes, the
// build-fail throw on an unresolved author citation, and composition with
// authored-link normalization, which owns Astro's base.

import { test, describe, after } from "node:test";
import assert from "node:assert/strict";
import { mkdir, mkdtemp, realpath, rm, symlink } from "node:fs/promises";
import os from "node:os";
import path from "node:path";

import { createAuthoredCitationResolver } from "../src/_internal/api/authored-citations.ts";
import { normalizeAuthoredLinks } from "../src/_internal/authored-links.ts";

const CONTENT = path.resolve("/tmp/nimbus-content");
const index = new Map<string, string>([
  ["zones:createZone", "/api/zones/create-zone"],
]);
const inScope = path.join(CONTENT, "guide.mdx");

function makeResolver(getCitationIndex = () => index) {
  return createAuthoredCitationResolver({ contentDirs: [CONTENT], getCitationIndex });
}

describe("createAuthoredCitationResolver", () => {
  test("resolves an in-scope citation to its logical route", () => {
    assert.equal(
      makeResolver()("See [create](api.ref:zones:createZone).", inScope),
      "See [create](/api/zones/create-zone/).",
    );
  });

  test("build-fails on an unresolved citation into a known collection", () => {
    assert.throws(
      () => makeResolver()("[x](api.ref:zones:deleteZone)", inScope),
      /unresolved API citation/,
    );
  });

  test("passes through files outside the content dirs and sourceless renders", () => {
    const source = "[x](api.ref:zones:deleteZone)";
    assert.equal(makeResolver()(source, "/somewhere/else/readme.md"), source);
    assert.equal(makeResolver()(source, undefined), source);
  });

  test("returns the source unchanged when it has no citation", () => {
    assert.equal(makeResolver()("Just **prose**.", inScope), "Just **prose**.");
  });

  test("reads the current index on every call (dev re-bake)", () => {
    let current: ReadonlyMap<string, string> = index;
    const resolve = makeResolver(() => current);
    assert.match(resolve("[a](api.ref:zones:createZone)", inScope), /create-zone/);
    current = new Map([["zones:createZone", "/api/zones/renamed"]]);
    assert.match(resolve("[a](api.ref:zones:createZone)", inScope), /renamed/);
  });

  describe("symlinked content roots", () => {
    let dir = "";
    after(() => (dir ? rm(dir, { recursive: true }) : undefined));

    test("scopes files reported by either their lexical or canonical path", async () => {
      dir = await mkdtemp(path.join(os.tmpdir(), "nimbus-cite-scope-"));
      const real = path.join(dir, "real");
      const linked = path.join(dir, "linked");
      await mkdir(path.join(real, "content"), { recursive: true });
      await symlink(real, linked, process.platform === "win32" ? "junction" : "dir");
      const resolve = createAuthoredCitationResolver({
        contentDirs: [path.join(linked, "content")],
        getCitationIndex: () => index,
      });
      const source = "[a](api.ref:zones:createZone)";
      const expected = "[a](/api/zones/create-zone/)";
      assert.equal(resolve(source, path.join(linked, "content", "a.mdx")), expected);
      assert.equal(
        resolve(source, path.join(await realpath(real), "content", "a.mdx")),
        expected,
      );
    });
  });

  test("composes with authored-link normalization: base applied once in every form", () => {
    const resolve = makeResolver();
    const mdx =
      '[a](api.ref:zones:createZone) [b](<api.ref:zones:createZone>) <a href="api.ref:zones:createZone">c</a>';
    assert.equal(
      normalizeAuthoredLinks(resolve(mdx, inScope), { base: "/docs/", format: "mdx" }),
      '[a](/docs/api/zones/create-zone/) [b](/docs/api/zones/create-zone/) <a href="/docs/api/zones/create-zone/">c</a>',
    );
    const md = "[a](<api.ref:zones:createZone>)\n\n<a href=\"api.ref:zones:createZone\">c</a>\n";
    assert.equal(
      normalizeAuthoredLinks(resolve(md, path.join(CONTENT, "guide.md")), {
        base: "/docs",
        format: "markdown",
      }),
      "[a](/docs/api/zones/create-zone/)\n\n<a href=\"/docs/api/zones/create-zone/\">c</a>\n",
    );
    assert.equal(
      normalizeAuthoredLinks(resolve(mdx, inScope), { base: "/", format: "mdx" }),
      resolve(mdx, inScope),
    );
  });
});

/**
 * Resolve `api.ref:` citations in authored `.md`/`.mdx` source to logical
 * (base-relative) routes. Authored-link normalization runs afterwards and owns
 * Astro's `base`, so citations get it exactly like hand-written links.
 */

import { realpathSync } from "node:fs";
import path from "node:path";

import { hasCitation, resolveCitations, type CitationIndex } from "./citations.js";
import type { PageLoadScope } from "../page-load-scope.js";

export interface AuthoredCitationOptions {
  contentDirs: ReadonlyArray<string>;
  getCitationIndex: () => CitationIndex;
  /** Citation keys of schemas with no page (`schemaPages: false`) → schema name. */
  getUnpublishedCitations?: () => ReadonlyMap<string, string>;
  /** A file outside `contentDirs` that a page or partials collection recorded. */
  isRecorded?: (filePath: string) => boolean;
  /**
   * The page collection whose load is rendering right now, if any. `glob()`
   * and in-memory loaders render `.md` inside the load, before anything is
   * recorded, so that render is in scope whatever its file.
   */
  getLoadScope?: () => PageLoadScope | undefined;
}

function canonical(directory: string): string {
  try {
    return realpathSync(directory);
  } catch {
    return directory;
  }
}

/**
 * Returns a source transform: `(source, filePath) => source` with in-scope
 * citations resolved. A malformed citation, or an unknown coordinate in a known
 * collection, throws (fails the build). A citation to an unknown collection
 * warns and renders `#`.
 */
export function createAuthoredCitationResolver(options: AuthoredCitationOptions) {
  const directories = [
    ...new Set(
      options.contentDirs.flatMap((dir) => {
        const absolute = path.resolve(dir);
        return [absolute, canonical(absolute)];
      }),
    ),
  ];
  const inScope = (filePath: string) =>
    directories.some(
      (dir) => filePath === dir || filePath.startsWith(dir + path.sep),
    );

  return (source: string, filePath: string | undefined): string => {
    if (!hasCitation(source)) return source;
    const absolute = filePath ? path.resolve(filePath) : undefined;
    const byFile =
      absolute !== undefined &&
      (inScope(absolute) || options.isRecorded?.(absolute) === true);
    const scope = byFile ? undefined : options.getLoadScope?.();
    if (!byFile && !scope) return source;

    const { code, diagnostics } = resolveCitations(source, {
      mode: "author",
      citationIndex: options.getCitationIndex(),
      unpublished: options.getUnpublishedCitations?.(),
    });
    const relative = absolute
      ? path.relative(process.cwd(), absolute)
      : `collection ${scope!.collection}`;
    const errors = diagnostics.filter((d) => d.level === "error");
    if (errors.length > 0) {
      throw new Error(
        `nimbus-docs: unresolved API citation in ${relative}:\n` +
          errors.map((e) => `  - ${e.message}`).join("\n"),
      );
    }
    for (const w of diagnostics) {
      if (w.level === "warning") {
        console.warn(`[nimbus:api:cite] ${relative}: ${w.message}`);
      }
    }
    return code;
  };
}

// Citation-index externality. The index (thousands of entries at
// full-spec scale) must never ride into the runtime Worker bundle. The structural
// guarantee — mirroring `api-parser-externality` — is that it lives in its own
// virtual module read only by a dedicated, dynamically-imported loader:
//
//   1. `virtual:nimbus/coordinates` is imported by EXACTLY ONE module,
//      `load-citation-index.ts`, and only via a dynamic `await import` (a split
//      point → its own lazy chunk, not the Worker entry).
//   2. `runtime-config.ts` — whose whole-namespace `virtual:nimbus/config`
//      import Rollup cannot per-export tree-shake — never references it.
//
// If either goes red, the citation index can leak into the runtime bundle.

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";

const SRC_ROOT = fileURLToPath(new URL("../src", import.meta.url));
const COORDINATES_MODULE = "virtual:nimbus/coordinates";

function collectTsFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = `${dir}/${entry.name}`;
    if (entry.isDirectory()) out.push(...collectTsFiles(full));
    else if (/\.tsx?$/.test(entry.name)) out.push(full);
  }
  return out;
}

const files = collectTsFiles(SRC_ROOT);

/** An `import … from "id"`, bare `import "id"`, or literal `import("id")`. A
 *  doc-comment mention or a plugin's id literal matches none of these. */
function importsModule(source: string, id: string): boolean {
  const q = id.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&");
  return (
    new RegExp(`\\bfrom\\s+["']${q}["']`).test(source) ||
    new RegExp(`\\bimport\\s+["']${q}["']`).test(source) ||
    new RegExp(`\\bimport\\s*\\(\\s*["']${q}["']\\s*\\)`).test(source)
  );
}

describe("citation-index externality", () => {
  test("only load-citation-index.ts imports virtual:nimbus/coordinates", () => {
    const referencing = files.filter((f) => importsModule(readFileSync(f, "utf8"), COORDINATES_MODULE));
    assert.deepEqual(
      referencing.map((f) => f.slice(SRC_ROOT.length)),
      ["/_internal/api/load-citation-index.ts"],
    );
  });

  test("load-citation-index reaches the module only through a dynamic import", () => {
    const src = readFileSync(`${SRC_ROOT}/_internal/api/load-citation-index.ts`, "utf8");
    assert.match(src, /await import\(\s*["']virtual:nimbus\/coordinates["']\s*\)/);
    assert.doesNotMatch(src, /\bfrom\s+["']virtual:nimbus\/coordinates["']/);
  });

  test("runtime-config never references the citation-index module", () => {
    const src = readFileSync(`${SRC_ROOT}/_internal/runtime-config.ts`, "utf8");
    assert.equal(src.includes(COORDINATES_MODULE), false);
  });
});

// Prose `api.ref:` citations must carry Astro's `base` in every output: the
// HTML from `.mdx` (Vite source plugin) and `.md` (Markdown processor), both
// prerendered and request-rendered, the Markdown alternate, and `llms-full.txt`.
// The citation index itself stays base-relative; each output applies the base
// exactly once.

import assert from "node:assert/strict";
import {
  mkdir,
  mkdtemp,
  readFile,
  rm,
  symlink,
  writeFile,
} from "node:fs/promises";
import path from "node:path";
import { afterEach, test } from "node:test";
import { pathToFileURL } from "node:url";

import { build, type AstroIntegration } from "astro";

import nimbus from "../src/index.ts";
import { runningNimbusVersion } from "../src/_internal/upgrades.ts";
import { TEST_TMP } from "./fixtures/temp-root.js";

const roots: string[] = [];

afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true })));
});

const moduleUrl = (relative: string) =>
  JSON.stringify(pathToFileURL(path.resolve(import.meta.dirname, relative)).href);

const GUIDE = `---
title: Guide
---
Bare [bare link](api.ref:api:create).

Angle [angle link](<api.ref:api:list>).

<a href="api.ref:api:openDispute">jsx link</a>

Versioned [versioned link](api.ref:api@v1:search).

Plain [plain link](/guide).

Code \`[kept](api.ref:api:create)\`.
`;

const REFERENCE_MD = `---
title: Reference
---
Markdown [md bare link](api.ref:api:create).

Markdown [md angle link](<api.ref:api:list>).

<a href="api.ref:api:openDispute">md html link</a>

Markdown [md versioned link](api.ref:api@v1:search).
`;

/** A minimal on-demand adapter: Astro's generated App behind the entrypoint. */
function testAdapter(entrypoint: string): AstroIntegration {
  return {
    name: "test:adapter",
    hooks: {
      "astro:config:done": ({ setAdapter }) => {
        setAdapter({
          name: "test:adapter",
          entrypointResolution: "auto",
          serverEntrypoint: entrypoint,
          supportedAstroFeatures: { serverOutput: "stable" },
        });
      },
    },
  };
}

interface Built {
  root: string;
  html: string;
  markdown: string;
  mdMarkdown: string;
  llmsFull: string;
  requestHtml?: string;
}

async function buildFixture(
  base: string,
  options: { request?: boolean } = {},
): Promise<Built> {
  // Deliberately not realpath'd: macOS tmpdir is a symlink, so this also
  // proves citation scoping survives a symlinked project root.
  const root = await mkdtemp(path.join(TEST_TMP, "nimbus-citation-base-"));
  roots.push(root);
  const write = async (relative: string, contents: string) => {
    await mkdir(path.dirname(path.join(root, relative)), { recursive: true });
    await writeFile(path.join(root, relative), contents, "utf8");
  };
  await write(
    "nimbus.json",
    `${JSON.stringify({ lastReviewedNimbusVersion: runningNimbusVersion() })}\n`,
  );
  await symlink(
    path.resolve(import.meta.dirname, "../node_modules"),
    path.join(root, "node_modules"),
    process.platform === "win32" ? "junction" : "dir",
  );
  const spec = path.resolve(import.meta.dirname, "fixtures/api/smallco.yaml");
  const api = [
    {
      collection: "api",
      versions: [
        { version: "v2", default: true, spec },
        { version: "v1", spec },
      ],
    },
  ];
  await write(
    "src/content.config.ts",
    `import { defineCollection } from "astro:content";
import { apiCollection, docsCollection } from ${moduleUrl("../src/content.ts")};
export const collections = {
  docs: defineCollection(docsCollection()),
  api: defineCollection(apiCollection(${JSON.stringify(api[0])})),
};`,
  );
  await write("src/content/docs/guide.mdx", GUIDE);
  await write("src/content/docs/reference.md", REFERENCE_MD);
  const renderGuide = `import { getEntry, render } from "astro:content";
const { Content } = await render(await getEntry("docs", "guide"));
const { Content: Reference } = await render(await getEntry("docs", "reference"));
---
<Content />
<Reference />`;
  await write("src/pages/index.astro", `---\nexport const prerender = true;\n${renderGuide}`);
  await write(
    "src/pages/[...slug]/index.md.ts",
    `import { getMarkdownPayload } from ${moduleUrl("../src/agent-endpoints.ts")};
import { getPreparedMarkdownRouteStaticPaths } from ${moduleUrl("../src/publication.ts")};
export const prerender = true;
export const getStaticPaths = () => getPreparedMarkdownRouteStaticPaths({ collection: "docs", surface: "markdown" });
export async function GET({ params, props, request }) {
  const payload = await getMarkdownPayload({ collection: "docs", surface: "markdown", slug: params.slug, reference: props.artifact, context: { request } });
  return new Response(payload.body, { headers: { "content-type": payload.mediaType } });
}`,
  );
  await write(
    "src/pages/llms-full.txt.ts",
    `import { getLlmsPayload } from ${moduleUrl("../src/agent-endpoints.ts")};
export const prerender = true;
export async function GET({ request }) {
  const payload = await getLlmsPayload({ scope: "site", surface: "full" }, { request });
  return new Response(payload.body, { headers: { "content-type": payload.mediaType } });
}`,
  );
  let adapter: AstroIntegration | undefined;
  if (options.request) {
    await write("src/pages/live.astro", `---\nexport const prerender = false;\n${renderGuide}`);
    await write(
      "server-entry.mjs",
      `import { createApp } from "astro/app/entrypoint";\nexport const app = createApp();\n`,
    );
    adapter = testAdapter(path.join(root, "server-entry.mjs"));
  }

  await build({
    root: pathToFileURL(`${root}${path.sep}`),
    cacheDir: path.join(root, ".astro"),
    outDir: "./dist",
    build: { server: path.join(root, ".server"), client: path.join(root, "dist") },
    vite: { cacheDir: path.join(root, ".vite") },
    base,
    ...(adapter ? { output: "server" as const, adapter } : {}),
    logLevel: "silent",
    integrations: [
      nimbus(
        {
          site: "https://example.test",
          title: "Test",
          description: "Test",
          search: false,
          api,
        },
        { admonitions: false, sitemap: false, validateMdx: false },
      ),
    ],
  });

  const built: Built = {
    root,
    html: await readFile(path.join(root, "dist/index.html"), "utf8"),
    markdown: await readFile(path.join(root, "dist/guide/index.md"), "utf8"),
    mdMarkdown: await readFile(path.join(root, "dist/reference/index.md"), "utf8"),
    llmsFull: await readFile(path.join(root, "dist/llms-full.txt"), "utf8"),
  };
  if (options.request) {
    const { app } = (await import(
      pathToFileURL(path.join(root, ".server/entry.mjs")).href
    )) as { app: { render(request: Request): Promise<Response> } };
    const prefix = base === "/" ? "" : base;
    const response = await app.render(new Request(`https://example.test${prefix}/live`));
    assert.equal(response.status, 200);
    built.requestHtml = await response.text();
  }
  return built;
}

function hrefs(html: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const match of html.matchAll(/<a href="([^"]*)"[^>]*>([^<]+)<\/a>/g)) {
    out[match[2]!] = match[1]!;
  }
  return out;
}

const EXPECTED_ROOT = {
  "bare link": "/api/charges/create/",
  "angle link": "/api/charges/list/",
  "jsx link": "/api/disputes/openDispute/",
  "versioned link": "/api/v1/search/search/",
  "plain link": "/guide",
  "md bare link": "/api/charges/create/",
  "md angle link": "/api/charges/list/",
  "md html link": "/api/disputes/openDispute/",
  "md versioned link": "/api/v1/search/search/",
};

function expected(prefix: string): Record<string, string> {
  return Object.fromEntries(
    Object.entries(EXPECTED_ROOT).map(([label, href]) => [label, `${prefix}${href}`]),
  );
}

test("prose citations carry a non-root base in HTML, Markdown, and llms-full.txt", async () => {
  const built = await buildFixture("/docs", { request: true });

  assert.deepEqual(hrefs(built.html), expected("/docs"));
  assert.deepEqual(hrefs(built.requestHtml!), expected("/docs"));
  assert.match(built.html, /<code>\[kept\]\(api\.ref:api:create\)<\/code>/);

  for (const markdown of [built.markdown, built.llmsFull]) {
    assert.match(markdown, /\[bare link\]\(\/docs\/api\/charges\/create\/\)/);
    assert.match(markdown, /\[angle link\]\(\/docs\/api\/charges\/list\/\)/);
    assert.match(markdown, /href="\/docs\/api\/disputes\/openDispute\/"/);
    assert.match(markdown, /\[versioned link\]\(\/docs\/api\/v1\/search\/search\/\)/);
  }
  for (const markdown of [built.mdMarkdown, built.llmsFull]) {
    assert.match(markdown, /\[md bare link\]\(\/docs\/api\/charges\/create\/\)/);
    assert.match(markdown, /\[md angle link\]\(\/docs\/api\/charges\/list\/\)/);
    assert.match(markdown, /href="\/docs\/api\/disputes\/openDispute\/">md html link/);
    assert.match(markdown, /\[md versioned link\]\(\/docs\/api\/v1\/search\/search\/\)/);
  }
  for (const output of [
    built.html,
    built.requestHtml!,
    built.markdown,
    built.mdMarkdown,
    built.llmsFull,
  ]) {
    assert.doesNotMatch(output, /\/docs\/docs\//);
  }
});

test("prose citations resolve without a prefix on a root base", async () => {
  const built = await buildFixture("/");

  assert.deepEqual(hrefs(built.html), expected(""));
  assert.match(built.markdown, /\[bare link\]\(\/api\/charges\/create\/\)/);
  assert.match(built.markdown, /\[versioned link\]\(\/api\/v1\/search\/search\/\)/);
  assert.match(built.llmsFull, /\[angle link\]\(\/api\/charges\/list\/\)/);
  assert.match(built.mdMarkdown, /\[md bare link\]\(\/api\/charges\/create\/\)/);
});

// The coordinate-citation resolver — the pure core. Citations become URLs and
// their grammar is frozen the moment the first guide ships, so this suite pins
// the token grammar (sentinel, @version, first-colon split), the two failure
// modes (author = build-error, derived = "#"), path-only value validation, and
// code protection. If this goes red, a frozen citation contract moved.

import { test, describe } from "node:test";
import assert from "node:assert/strict";

import {
  CITATION_SENTINEL,
  citationKey,
  parseCitation,
  resolveCitation,
  resolveCitations,
  isSafeCitationPath,
  hasCitation,
  type CitationIndex,
} from "../src/_internal/api/citations.ts";
import { setLinkPolicy } from "../src/_internal/url.ts";

const index: CitationIndex = new Map([
  ["zones:createZone", "/zones/create"],
  ["zones@v2:createZone", "/zones/create"],
  ["zones@v1:createZone", "/zones/v1/create"],
  ["accounts:list", "/accounts/list"],
  // a spaced-tag section coordinate stays opaque (`tags.<label>`) but routes to
  // a slugified URL — a real space-bearing citation key, reachable only via the
  // angle-bracket destination form.
  ["zones:tags.User Management", "/zones/tags/User-Management"],
]);

describe("parseCitation: the token grammar", () => {
  test("a non-sentinel target is not a citation", () => {
    assert.equal(parseCitation("/zones/create"), null);
    assert.equal(parseCitation("https://example.com"), null);
    assert.equal(parseCitation("mailto:x@y.z"), null);
  });

  test("bare collection:coordinate", () => {
    assert.deepEqual(parseCitation("api.ref:zones:createZone"), {
      collection: "zones",
      coordinate: "createZone",
    });
  });

  test("versioned collection@version:coordinate", () => {
    assert.deepEqual(parseCitation("api.ref:zones@v2:createZone"), {
      collection: "zones",
      version: "v2",
      coordinate: "createZone",
    });
  });

  test("the coordinate is never re-split — dots and later colons survive", () => {
    assert.deepEqual(parseCitation("api.ref:zones:createZone.amount"), {
      collection: "zones",
      coordinate: "createZone.amount",
    });
    // a colon inside the coordinate belongs to the coordinate (first-colon split)
    assert.deepEqual(parseCitation("api.ref:zones:a.b:c"), {
      collection: "zones",
      coordinate: "a.b:c",
    });
  });

  test("malformed tokens are faults, not passthroughs", () => {
    assert.ok("fault" in (parseCitation("api.ref:zonesCreateZone") as object)); // no colon
    assert.ok("fault" in (parseCitation("api.ref:zones:") as object)); // empty coordinate
    assert.ok("fault" in (parseCitation("api.ref:Zones:x") as object)); // uppercase collection
    assert.ok("fault" in (parseCitation("api.ref:zones@v2@v3:x") as object)); // two @
    assert.ok("fault" in (parseCitation("api.ref:zones@v_2:x") as object)); // bad version char
    assert.ok("fault" in (parseCitation("api.ref:zones@v2.:x") as object)); // trailing dot
  });

  test("realistic versions parse", () => {
    for (const v of ["v1", "v2", "2024-01-01", "1.0.0", "v2-beta"]) {
      assert.deepEqual(parseCitation(`api.ref:zones@${v}:createZone`), {
        collection: "zones",
        version: v,
        coordinate: "createZone",
      });
    }
  });
});

describe("citationKey + resolveCitation", () => {
  test("unversioned key resolves the family default", () => {
    assert.equal(resolveCitation({ collection: "zones", coordinate: "createZone" }, index), "/zones/create/");
  });
  test("versioned key resolves that version", () => {
    assert.equal(
      resolveCitation({ collection: "zones", version: "v1", coordinate: "createZone" }, index),
      "/zones/v1/create/",
    );
  });
  test("unknown resolves to undefined", () => {
    assert.equal(resolveCitation({ collection: "zones", coordinate: "nope" }, index), undefined);
  });
  test("resolved URLs follow Astro's trailingSlash like other page links", (t) => {
    t.after(() => setLinkPolicy({ trailingSlash: "ignore", format: "directory" }));
    setLinkPolicy({ trailingSlash: "never", format: "directory" });
    assert.equal(resolveCitation({ collection: "zones", coordinate: "createZone" }, index), "/zones/create");
    assert.equal(
      resolveCitations("[a](api.ref:zones:createZone)", { mode: "author", citationIndex: index }).code,
      "[a](/zones/create)",
    );
    setLinkPolicy({ trailingSlash: "always", format: "directory" });
    assert.equal(resolveCitation({ collection: "zones", coordinate: "createZone" }, index), "/zones/create/");
  });
  test("key shape", () => {
    assert.equal(citationKey("zones", undefined, "createZone"), "zones:createZone");
    assert.equal(citationKey("zones", "v1", "createZone"), "zones@v1:createZone");
  });
});

describe("isSafeCitationPath: value validation on ingest", () => {
  test("accepts single-slash site-absolute paths", () => {
    assert.ok(isSafeCitationPath("/zones/create"));
    assert.ok(isSafeCitationPath("/"));
  });
  test("rejects schemes, protocol-relative, non-absolute, and unsafe chars", () => {
    assert.equal(isSafeCitationPath("javascript:alert(1)"), false);
    assert.equal(isSafeCitationPath("data:text/html,x"), false);
    assert.equal(isSafeCitationPath("//evil.example.com"), false);
    assert.equal(isSafeCitationPath("https://evil.example.com/x"), false);
    assert.equal(isSafeCitationPath("zones/create"), false);
    assert.equal(isSafeCitationPath("/has space"), false);
    assert.equal(isSafeCitationPath("/has\\backslash"), false);
  });
});

describe("resolveCitations: rewriting link targets", () => {
  test("rewrites a markdown link to its resolved URL", () => {
    const { code, diagnostics } = resolveCitations(
      "See [create a zone](api.ref:zones:createZone) to start.",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "See [create a zone](/zones/create/) to start.");
    assert.equal(diagnostics.length, 0);
  });

  test("rewrites a JSX href", () => {
    const { code } = resolveCitations(
      `<a href="api.ref:accounts:list">list</a>`,
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, `<a href="/accounts/list/">list</a>`);
  });

  test("rewrites a versioned citation", () => {
    const { code } = resolveCitations(
      "[old](api.ref:zones@v1:createZone)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[old](/zones/v1/create/)");
  });

  test("author mode: unknown coordinate is a build error, no token leaks", () => {
    const { code, diagnostics } = resolveCitations(
      "[gone](api.ref:zones:deleteZone)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[gone](#)");
    assert.equal(diagnostics.length, 1);
    assert.equal(diagnostics[0]?.level, "error");
  });

  test("author mode: an unknown collection is soft (warn + #), never wedges", () => {
    // a declared-but-unreachable remote, or a typo'd collection name: we are
    // not authoritative, so it must not fail the build.
    const { code, diagnostics } = resolveCitations(
      "[x](api.ref:widgets:makeWidget)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[x](#)");
    assert.equal(diagnostics.length, 1);
    assert.equal(diagnostics[0]?.level, "warning");
    assert.match(diagnostics[0]?.message ?? "", /unknown collection "widgets"/);
  });

  test("derived mode: unknown coordinate warns and renders #", () => {
    const { code, diagnostics } = resolveCitations(
      "[x](api.ref:zones:deleteZone)",
      { mode: "derived", citationIndex: index },
    );
    assert.equal(code, "[x](#)");
    assert.equal(diagnostics.length, 1);
    assert.equal(diagnostics[0]?.level, "warning");
  });

  test("a request field that is only listed under the response points there", () => {
    const withResponse: CitationIndex = new Map([
      ...index,
      ["zones:createZone.response.201", "/api/zones/create-zone/#response-201"],
      ["zones:createZone.response.201.id", "/api/zones/create-zone/#response-201-id"],
    ]);
    const { diagnostics } = resolveCitations("[x](api.ref:zones:createZone.id)", { mode: "author", citationIndex: withResponse });
    assert.equal(diagnostics[0]?.level, "error");
    assert.match(diagnostics[0]?.message ?? "", /leave out readOnly fields; if it is readOnly, cite it under the response: "api\.ref:zones:createZone\.response\.201\.id"/);
  });

  test("a dotted operation ID never suggests a response from another operation", () => {
    const withResponse: CitationIndex = new Map([
      ...index,
      ["zones:users", "/api/zones/users"],
      ["zones:users.create", "/api/zones/users/create"],
      ["zones:users.response.201", "/api/zones/users/#response-201"],
      ["zones:users.response.201.create.id", "/api/zones/users/#response-201-create-id"],
      ["zones:users.create.response.201", "/api/zones/users/create/#response-201"],
      ["zones:users.create.response.201.id", "/api/zones/users/create/#response-201-id"],
    ]);
    const { diagnostics } = resolveCitations("[x](api.ref:zones:users.create.id)", { mode: "author", citationIndex: withResponse });
    assert.match(diagnostics[0]?.message ?? "", /"api\.ref:zones:users\.create\.response\.201\.id"/);
    assert.doesNotMatch(diagnostics[0]?.message ?? "", /"api\.ref:zones:users\.response\.201\.create\.id"/);
  });

  test("a nested field and an additional response media field suggest their response coordinates", () => {
    const withResponse: CitationIndex = new Map([
      ...index,
      ["zones:createZone.profile", "/zones/create/#request-profile"],
      ["zones:createZone.response.201", "/zones/create/#response-201"],
      ["zones:createZone.response.201.profile.id", "/zones/create/#response-201-profile-id"],
      ["zones:createZone.response.201.text-csv", "/zones/create/#response-201-text-csv"],
      ["zones:createZone.response.201.text-csv.code", "/zones/create/#response-201-text-csv-code"],
    ]);
    for (const [field, target] of [
      ["profile.id", "createZone.response.201.profile.id"],
      ["code", "createZone.response.201.text-csv.code"],
    ]) {
      const { diagnostics } = resolveCitations(`[x](api.ref:zones:createZone.${field})`, { mode: "author", citationIndex: withResponse });
      assert.ok(diagnostics[0]?.message.includes(`"api.ref:zones:${target}"`), diagnostics[0]?.message);
    }
  });

  test("a near-miss gets a Levenshtein hint", () => {
    const { diagnostics } = resolveCitations(
      "[x](api.ref:zones:createZon)",
      { mode: "author", citationIndex: index },
    );
    assert.match(diagnostics[0]?.message ?? "", /Did you mean "api\.ref:zones:createZone"/);
  });

  test("a malformed token is always an error, both modes", () => {
    for (const mode of ["author", "derived"] as const) {
      const { code, diagnostics } = resolveCitations("[x](api.ref:zones:)", { mode, citationIndex: index });
      assert.equal(code, "[x](#)");
      assert.equal(diagnostics[0]?.level, "error");
    }
  });

  test("citations inside code are never rewritten or reported", () => {
    const src = "Write `api.ref:zones:createZone` in a link.\n\n```md\n[x](api.ref:zones:deleteZone)\n```\n";
    const { code, diagnostics } = resolveCitations(src, { mode: "author", citationIndex: index });
    assert.equal(code, src);
    assert.equal(diagnostics.length, 0);
  });

  test("a longer fence keeps the shorter fence inside it as code", () => {
    const src = "````md\n```\n[x](api.ref:zones:nope)\n```\n````\n";
    const { code, diagnostics } = resolveCitations(src, { mode: "author", citationIndex: index });
    assert.equal(code, src);
    assert.equal(diagnostics.length, 0);
  });

  test("multiple citations in one source all resolve", () => {
    const { code } = resolveCitations(
      "[a](api.ref:zones:createZone) and [b](api.ref:accounts:list)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[a](/zones/create/) and [b](/accounts/list/)");
  });

  test("angle-bracket destination cites a space-bearing coordinate; brackets are dropped", () => {
    const { code, diagnostics } = resolveCitations(
      "[section](<api.ref:zones:tags.User Management>)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[section](/zones/tags/User-Management/)");
    assert.equal(diagnostics.length, 0);
  });

  test("angle-bracket destination also works for an ordinary coordinate", () => {
    const { code } = resolveCitations(
      "[c](<api.ref:zones:createZone>)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[c](/zones/create/)");
  });

  test("interior padding inside the angle brackets is tolerated and trimmed", () => {
    for (const src of [
      "[a](< api.ref:zones:tags.User Management>)",
      "[b](<api.ref:zones:tags.User Management >)",
      "[c](<  api.ref:zones:tags.User Management  >)",
    ]) {
      const { code, diagnostics } = resolveCitations(src, { mode: "author", citationIndex: index });
      assert.match(code, /\]\(\/zones\/tags\/User-Management\/\)/);
      assert.equal(diagnostics.length, 0);
    }
  });

  test("a JSX href with a space-bearing coordinate resolves (quote-delimited, not whitespace-truncated)", () => {
    const { code, diagnostics } = resolveCitations(
      `<a href="api.ref:zones:tags.User Management">section</a>`,
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, `<a href="/zones/tags/User-Management/">section</a>`);
    assert.equal(diagnostics.length, 0);
  });

  test("an unresolved space-bearing coordinate still fails in author mode", () => {
    const { code, diagnostics } = resolveCitations(
      "[x](<api.ref:zones:GET /widgets>)",
      { mode: "author", citationIndex: index },
    );
    assert.equal(code, "[x](#)");
    assert.equal(diagnostics[0]?.level, "error");
  });
});

describe("hasCitation: the fail-loud pre-filter", () => {
  test("true when a citation link is present outside code", () => {
    assert.ok(hasCitation("[x](api.ref:zones:createZone)"));
  });
  test("true for an angle-bracket destination", () => {
    assert.ok(hasCitation("[x](<api.ref:zones:GET /zones>)"));
  });
  test("true for an angle destination with interior padding (no silent leak)", () => {
    assert.ok(hasCitation("[x](< api.ref:zones:GET /zones >)"));
  });
  test("false when the only occurrence is inside code", () => {
    assert.equal(hasCitation("`api.ref:zones:createZone`"), false);
  });
  test("false when the sentinel is mentioned in prose, not linked", () => {
    assert.equal(hasCitation("Cite an op with the api.ref: link scheme."), false);
  });
  test("false for ordinary prose", () => {
    assert.equal(hasCitation("no citations here"), false);
  });
  test("the sentinel export is stable", () => {
    assert.equal(CITATION_SENTINEL, "api.ref:");
  });
});

// The citation-index producer — the coordinate → URL contract the resolver reads.
// Pins URL formation (mount path per D18), the default/versioned key pair, the
// published manifest shape, and remote-manifest ingest with path-only value
// validation + trusted origin. If this goes red, the citation contract moved.

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";

import { buildCitationIndex, ingestRemoteManifest, type CoordinatesManifest } from "../src/_internal/api/citation-index.ts";
import { resolveCitations } from "../src/_internal/api/citations.ts";
import type { ApiSpec } from "../src/types.ts";

function fixturePath(rel: string): string {
  return fileURLToPath(new URL(`./fixtures/api/${rel}`, import.meta.url));
}

const root = fileURLToPath(new URL(".", import.meta.url));

describe("buildCitationIndex: unversioned collection", () => {
  const api: ApiSpec[] = [{ collection: "smallco", spec: fixturePath("smallco.yaml"), schemaPages: true }];

  test("keys pages under collection:coordinate with site-absolute /collection URLs", async () => {
    const { index } = await buildCitationIndex(api, root);
    assert.ok(index.size > 0);
    // the root page maps to the bare mount path
    assert.equal(index.get("smallco:smallco"), "/smallco");
    // every value is a site-absolute path under the mount
    for (const [, url] of index) assert.match(url, /^\/smallco(\/.*)?$/);
  });

  test("manifest carries the collection with a null defaultVersion", async () => {
    const { manifest } = await buildCitationIndex(api, root);
    assert.equal(manifest.version, 2);
    assert.equal(manifest.collections.smallco?.defaultVersion, null);
    assert.ok(manifest.collections.smallco!.pages.length > 0);
    assert.equal(manifest.collections.smallco!.versions, undefined);
    assert.deepEqual(read(manifest), (await buildCitationIndex(api, root)).index);
  });

  test("manifest maps are null-prototype (a '__proto__'/'constructor' key can never pollute)", async () => {
    const { manifest } = await buildCitationIndex(api, root);
    assert.equal(Object.getPrototypeOf(manifest.collections), null);
    assert.equal(Object.getPrototypeOf(manifest.collections.smallco!.pages[0]!.entries), null);
  });
});

describe("buildCitationIndex: versioned family (v2 default + v1)", () => {
  const spec = fixturePath("smallco.yaml");
  const api: ApiSpec[] = [
    {
      collection: "svc",
      versions: [
        { version: "v2", default: true, spec },
        { version: "v1", spec },
      ],
    },
  ];

  test("default version is addressable both bare and @-qualified; v1 lives under /svc/v1", async () => {
    const { index, manifest } = await buildCitationIndex(api, root);
    // default (v2): bare key → /svc, and @v2 key → /svc
    assert.equal(index.get("svc:svc"), "/svc");
    assert.equal(index.get("svc@v2:svc"), "/svc");
    // non-default (v1): only the @v1 key exists, under /svc/v1 — no bare alias
    assert.equal(index.get("svc@v1:svc"), "/svc/v1");
    assert.equal(
      index.get("svc:create.response.200"),
      `${index.get("svc:create")}#response-200`,
    );
    assert.equal(
      index.get("svc@v1:create.response.200"),
      `${index.get("svc@v1:create")}#response-200`,
    );
    assert.equal(manifest.collections.svc?.defaultVersion, "v2");
  });
});

describe("buildCitationIndex: field coordinates resolve to <page>#<anchor>", () => {
  const api: ApiSpec[] = [{ collection: "smallco", spec: fixturePath("smallco.yaml"), schemaPages: true }];

  test("a body field, a parameter, and a schema field each cite their owning page plus a lossless anchor", async () => {
    const { index } = await buildCitationIndex(api, root);
    // The anchor is the coordinate itself when it is already fragment-safe, so
    // the field URL is exactly the owning page's URL plus that fragment.
    assert.equal(index.get("smallco:create.amount"), `${index.get("smallco:create")}#create.amount`);
    assert.equal(index.get("smallco:list.query.limit"), `${index.get("smallco:list")}#list.query.limit`);
    assert.equal(index.get("smallco:Charge.amount"), `${index.get("smallco:Charge")}#Charge.amount`);
  });

  test("a colon-bearing field name yields a fragment-safe (sanitized + disambiguated) anchor", async () => {
    const { index } = await buildCitationIndex(api, root);
    const url = index.get("smallco:search.static:wan");
    assert.ok(url, "the hostile body property is citeable");
    const [pageUrl, fragment] = url!.split("#");
    assert.equal(pageUrl, index.get("smallco:search"));
    // ':' is not fragment-safe, so it is rewritten and a lossless base32 suffix
    // appended for injectivity.
    assert.match(fragment, /^search\.static-wan--[a-z2-7]+$/);
    assert.ok(!fragment.includes(":"));
  });

  test("field coordinates are published in the manifest alongside pages", async () => {
    const { manifest } = await buildCitationIndex(api, root);
    assert.match(read(manifest).get("smallco:create.amount")!, /#create\.amount$/);
  });
});

describe("buildCitationIndex: response coordinates resolve to rendered anchors", () => {
  const api: ApiSpec[] = [{ collection: "smallco", spec: fixturePath("smallco.yaml"), schemaPages: true }];

  test("bare responses are addressable in the index and manifest", async () => {
    const { index, manifest } = await buildCitationIndex(api, root);
    assert.equal(
      index.get("smallco:create.response.200"),
      `${index.get("smallco:create")}#response-200`,
    );
    assert.equal(
      read(manifest).get("smallco:create.response.200"),
      `${index.get("smallco:create")}#response-200`,
    );
  });

  test("deviant response statuses use the exact rendered anchor", async () => {
    const { index } = await buildCitationIndex(
      [{ collection: "dev", spec: fixturePath("deviant.yaml"), schemaPages: true }],
      root,
    );
    assert.equal(
      index.get("dev:listWidgets.response.4xx"),
      `${index.get("dev:listWidgets")}#response-4xx`,
    );
  });

  test("punctuation in a response status is sanitized losslessly", async () => {
    const spec = {
      openapi: "3.0.3",
      info: { title: "Odd status", version: "1.0.0" },
      paths: {
        "/odd": {
          get: {
            operationId: "oddStatus",
            responses: { "2:00": { description: "ok" } },
          },
        },
      },
    };
    const { index } = await buildCitationIndex(
      [{ collection: "odd", spec, schemaPages: true }],
      root,
    );
    const url = index.get("odd:oddStatus.response.2:00");
    assert.ok(url);
    assert.match(url, /#response-2-00--[a-z2-7]+$/);
    assert.ok(!url.split("#")[1]!.includes(":"));
  });
});


function read(manifest: CoordinatesManifest) {
  const index = new Map<string, string>();
  for (const name of Object.keys(manifest.collections)) {
    assert.deepEqual(ingestRemoteManifest(index, name, JSON.parse(JSON.stringify(manifest))), []);
  }
  return index;
}

describe("prepared API citations: historical authored lookup without published history", () => {
  test("cached summaries avoid parsing and preserve old fields and responses", async () => {
    const reads = new Map<string, number>();
    const versions = ["v3", "v2", "v1"];
    const preparedVersions = new Map(
      versions.map((version) => [
        `svc@${version}`,
        {
          read() {
            reads.set(version, (reads.get(version) ?? 0) + 1);
            return {
              targets: [
                { coordinate: "svc", slug: "" },
                { coordinate: `operation-${version}`, slug: `slug-${version}` },
                ...(version === "v2" ? [{ coordinate: `operation-${version}.profile`, slug: `slug-${version}`, anchor: "request-profile" }] : []),
                ...(version === "v2" ? [{ coordinate: `operation-${version}.response.201`, slug: `slug-${version}`, anchor: "response-201" }] : []),
                {
                  coordinate: `operation-${version}.field`,
                  slug: `slug-${version}`,
                  anchor: "field",
                },
                {
                  coordinate: `operation-${version}.response.200`,
                  slug: `slug-${version}`,
                  anchor: "response-200",
                },
                ...(version === "v2" ? [{ coordinate: `operation-${version}.response.201.hidden`, slug: `slug-${version}`, anchor: "response-201-hidden" }] : []),
                ...(version === "v2" ? [{ coordinate: `operation-${version}.response.201.profile.hidden`, slug: `slug-${version}`, anchor: "response-201-profile-hidden" }] : []),
              ],
              unpublished: { UnpublishedSchema: "UnpublishedSchema" },
            };
          },
        },
      ]),
    );
    const { index, manifest, unpublished } = await buildCitationIndex(
      [
        {
          collection: "svc",
          versionUrl: { in: "query" },
          versions: versions.map((version, i) => ({
            version,
            spec: "/does/not/exist.json",
            default: i === 0,
          })),
        },
      ],
      root,
      { preparedVersions },
    );
    assert.equal(reads.get("v3"), 1);
    assert.equal(reads.has("v2"), false);
    assert.equal(
      index.get("svc@v2:operation-v2.field"),
      "/svc/slug-v2?version=v2#field",
    );
    assert.equal(
      index.get("svc@v2:operation-v2.response.200"),
      "/svc/slug-v2?version=v2#response-200",
    );
    assert.equal(
      unpublished.get("svc@v2:UnpublishedSchema"),
      "UnpublishedSchema",
    );
    assert.equal(
      reads.get("v2"),
      1,
      "one summary read serves all fields and diagnostics in this version",
    );
    assert.equal(index.has("svc@v2:operation-v2"), true);
    const { diagnostics } = resolveCitations("[x](api.ref:svc@v2:operation-v2.hidden)", { mode: "author", citationIndex: index });
    assert.match(diagnostics[0]?.message ?? "", /cite it under the response: "api\.ref:svc@v2:operation-v2\.response\.201\.hidden"/);
    const nested = resolveCitations("[x](api.ref:svc@v2:operation-v2.profile.hidden)", { mode: "author", citationIndex: index });
    assert.match(nested.diagnostics[0]?.message ?? "", /cite it under the response: "api\.ref:svc@v2:operation-v2\.response\.201\.profile\.hidden"/);
    assert.equal(reads.get("v2"), 1, "the hint reuses the cached historical version");
    assert.equal(
      index.get("svc@v1:operation-v1"),
      "/svc/slug-v1?version=v1",
    );
    assert.equal(
      index.get("svc@v2:operation-v2"),
      "/svc/slug-v2?version=v2",
    );
    assert.equal(reads.get("v2"), 2, "cache retains one historical version");
    assert.equal(index.get("svc@missing:operation-v2"), undefined);
    assert.equal(index.get("svc@v2:missing"), undefined);
    assert.deepEqual(Object.keys(manifest.collections.svc!.versions!), ["v3"]);
    assert.ok(
      [...index.keys()].every(
        (key) => !key.includes("@v1:") && !key.includes("@v2:"),
      ),
    );
    assert.doesNotMatch(
      JSON.stringify(Object.fromEntries(index)),
      /operation-v[12]/,
      "virtual module contains published default only even after authored reads",
    );
  });
});

// Regression guards for two robustness fixes on the `./api` seam:
//   1. The build cache is keyed by a collision-resistant digest (SHA-256), so
//      two DIFFERENT specs never alias to one cached model.
//   2. The cached nav base is deep-frozen, so a consumer mutating the returned
//      nav can't poison every later `getApiNav` call.

import { test, describe } from "node:test";
import assert from "node:assert/strict";

import {
  buildApiModel,
  getApiNav,
  getApiPageSlugs,
  clearApiModelCache,
} from "../src/api/index.js";

const specA = `
openapi: 3.1.0
info: { title: A, version: "1" }
paths:
  /alpha:
    get:
      operationId: getAlpha
      responses:
        "200": { description: ok }
`;

const specB = `
openapi: 3.1.0
info: { title: B, version: "1" }
paths:
  /beta:
    get:
      operationId: getBeta
      responses:
        "200": { description: ok }
`;

describe("api build cache: collision-resistant key", () => {
  test("two DIFFERENT specs on one collection do not alias", async () => {
    clearApiModelCache("cache-distinct");

    const a = await buildApiModel({ collection: "cache-distinct", spec: specA });
    const b = await buildApiModel({ collection: "cache-distinct", spec: specB });

    const slugsA = getApiPageSlugs(a)
      .map((s) => s.slug)
      .sort();
    const slugsB = getApiPageSlugs(b)
      .map((s) => s.slug)
      .sort();

    assert.notDeepEqual(
      slugsA,
      slugsB,
      "the second build must not return the first spec's cached model",
    );
    assert.ok(
      slugsA.includes("getAlpha"),
      "spec A resolves its own operation",
    );
    assert.ok(
      slugsB.includes("getBeta"),
      "spec B resolves its own operation",
    );
  });

  test("building the SAME bytes twice returns consistent slugs", async () => {
    clearApiModelCache("cache-same");

    const first = await buildApiModel({ collection: "cache-same", spec: specA });
    const second = await buildApiModel({ collection: "cache-same", spec: specA });

    assert.deepEqual(getApiPageSlugs(first), getApiPageSlugs(second));
  });
});

describe("api nav: cached base is immutable", () => {
  test("mutating a returned nav item cannot poison later reads", async () => {
    clearApiModelCache("nav-frozen");

    const model = await buildApiModel({
      collection: "nav-frozen",
      spec: specA,
    });

    const nav = getApiNav(model);
    assert.ok(nav.items.length > 0, "nav has at least one root item");
    const original = nav.items[0].label;

    // Frozen data: the write either throws (strict mode) or is a silent no-op.
    // Either way the cached base must survive uncorrupted.
    try {
      nav.items[0].label = "POISON";
    } catch {
      /* frozen — expected in strict mode */
    }

    const reread = getApiNav(model).items[0].label;
    assert.equal(
      reread,
      original,
      "a later getApiNav read must not see the poisoned label",
    );
    assert.notEqual(reread, "POISON");
  });
});

/**
 * The citation-index producer — turns the `api[]` declaration into the
 * coordinate → URL contract the citation resolver reads. One build yields
 * `index` (the flat map, consumed directly and baked into
 * `virtual:nimbus/coordinates`) and `manifest` (the published `coordinates.json`
 * payload). Version lives in the path via `mountPath`, never in the coordinate.
 */

import { apiVersionQuery, targetUrlFields } from "./resolve-versions.js";
import { projectMountContext } from "../project-mount-context.js";
import {
  buildApiModel,
  type ApiModel,
  getApiFieldCitations,
  getApiPageProps,
  getApiPageSlugs,
} from "../../api/index.js";
import type { ApiSpec } from "../../types.js";
import type { Coordinate, DocsModel } from "./model.js";
import { unwrapModel } from "./model-handle.js";
import { createPageGroups } from "./coordinate-manifest.js";
import { citationKey, isSafeCitationPath } from "./citations.js";
import { resolveSpecSource } from "./resolve-spec.js";
import {
  resolveAllApiCollections,
  type ResolvedApiVersion,
} from "./resolve-versions.js";

export type { CoordinatesManifest } from "../../types.js";
import type { CoordinatesManifest } from "../../types.js";

export interface CitationIndexResult {
  /** `collection:coordinate` / `collection@version:coordinate` → URL. */
  index: Map<string, string>;
  manifest: CoordinatesManifest;
  /**
   * Citation keys that name a real schema or schema field of a collection with
   * `schemaPages: false` → the schema's name. They have no page to resolve to, so
   * they stay out of `index`; this lets an authored citation fail with a named
   * reason instead of "does not resolve".
   */
  unpublished: Map<string, string>;
}

/** Schema and schema-field coordinates whose schema has no page, mapped to the
 *  schema's name. A field is attributed by walking its parent chain to the
 *  schema node (nested fields parent to their container field). */
function pagelessSchemaCoordinates(model: DocsModel): Map<Coordinate, string> {
  const owner = new Map<Coordinate, string | null>();
  const schemaOf = (coordinate: Coordinate): string | null => {
    const known = owner.get(coordinate);
    if (known !== undefined) return known;
    const node = model.nodes.get(coordinate);
    let result: string | null = null;
    if (node?.kind === "schema" && node.facts.kind === "schema") {
      result = model.pages.pages.has(coordinate) ? null : node.facts.name;
    } else if (node?.kind === "field" && node.parent !== null) {
      result = schemaOf(node.parent);
    }
    owner.set(coordinate, result);
    return result;
  };
  const out = new Map<Coordinate, string>();
  for (const node of model.nodes.values()) {
    if (node.kind !== "schema" && node.kind !== "field") continue;
    const schema = schemaOf(node.id);
    if (schema !== null) out.set(node.id, schema);
  }
  return out;
}

function pageUrl(
  target: {
    familyPath: string;
    mountPath: string;
    versionMode: "path" | "query";
    versionParam: string;
    isDefault: boolean;
    version: string | null;
  },
  slug: string,
): string {
  // Query mode: one version-free path per operation; a non-default version's
  // citations carry its version query (`resolveCitation` shapes only the
  // pathname, so the query survives `toDocumentHref`).
  const base =
    target.versionMode === "query" ? target.familyPath : target.mountPath;
  const path = slug === "" ? base : `${base}/${slug}`;
  return `${path}${apiVersionQuery(target)}`;
}

/** Version-neutral build artifact; never embedded in request indexes. */
export interface ApiCitationSummary {
  targets: Array<{ coordinate: string; slug: string; anchor?: string }>;
  unpublished: Record<string, string>;
}

/** `schemaPages` true publishes every schema, so none is unpublished (as in 0.17). */
export function collectApiCitationSummary(
  model: ApiModel,
  schemaPages = false,
): ApiCitationSummary {
  const targets: ApiCitationSummary["targets"] = [];
  for (const { coordinate, slug } of getApiPageSlugs(model)) {
    targets.push({ coordinate, slug });
    const page = getApiPageProps(model, coordinate);
    if (page.kind === "operation") {
      for (const response of page.responses) {
        targets.push({
          coordinate: response.coordinate,
          slug,
          anchor: response.anchor,
        });
      }
    }
  }
  for (const { coordinate, slug, anchor } of getApiFieldCitations(model)) {
    targets.push({ coordinate, slug, anchor });
  }
  return {
    targets,
    unpublished: schemaPages
      ? {}
      : Object.fromEntries(pagelessSchemaCoordinates(unwrapModel(model))),
  };
}

export interface PreparedApiCitationSource {
  /** Build-only synchronous reader; retain a filename, not all version payloads. */
  read(): ApiCitationSummary;
}

export interface BuildCitationIndexOptions {
  preparedVersions?: ReadonlyMap<string, PreparedApiCitationSource>;
}

/** Iteration deliberately exposes published citations only; authored resolution
 * can still look up exact historical versions without bundling their history. */
class AuthoredCitationMap extends Map<string, string> {
  constructor(
    private readonly historical: (key: string) => string | undefined,
    private readonly historicalKeys: (scope: string) => Iterable<string>,
  ) {
    super();
  }
  override get(key: string): string | undefined {
    return super.get(key) ?? this.historical(key);
  }
  override has(key: string): boolean {
    return super.has(key) || this.historical(key) !== undefined;
  }
  keysForVersion(scope: string): Iterable<string> {
    return this.historicalKeys(scope);
  }
}

/**
 * Build the citation index + manifest for every declared collection and version.
 * Reuses `buildApiModel`'s content-addressed cache, so a spec parsed here is not
 * re-parsed by the render path. A URL that fails `isSafeCitationPath` is dropped
 * (it can never be a valid page URL) rather than baked.
 */
export async function buildCitationIndex(
  api: ApiSpec[] | undefined,
  root: string,
  options: BuildCitationIndexOptions = {},
): Promise<CitationIndexResult> {
  const historical = new Map<
    string,
    { target: ResolvedApiVersion; source: PreparedApiCitationSource }
  >();
  // Bound build-time demand reads to one historical version. Repeated citations
  // in a document reuse it; different documents cannot retain all history.
  let cached:
    | {
        key: string;
        index: Map<string, string>;
        unpublished: Map<string, string>;
      }
    | undefined;
  const lookup = (key: string, kind: "index" | "unpublished") => {
    const colon = key.indexOf(":");
    if (colon < 0) return undefined;
    const versionKey = key.slice(0, colon);
    const prepared = historical.get(versionKey);
    if (!prepared) return undefined;
    if (cached?.key !== versionKey) {
      const summary = prepared.source.read();
      const index = new Map<string, string>();
      const unpublished = new Map<string, string>();
      for (const { coordinate, slug, anchor } of summary.targets) {
        const url = `${pageUrl(prepared.target, slug)}${anchor === undefined ? "" : `#${anchor}`}`;
        if (isSafeCitationPath(url))
          index.set(`${versionKey}:${coordinate}`, url);
      }
      for (const [coordinate, schema] of Object.entries(summary.unpublished)) {
        unpublished.set(`${versionKey}:${coordinate}`, schema);
      }
      cached = { key: versionKey, index, unpublished };
    }
    return cached[kind].get(key);
  };
  const index = options.preparedVersions
    ? new AuthoredCitationMap((key) => lookup(key, "index"), (scope) => {
        lookup(`${scope}:`, "index");
        return cached?.key === scope ? cached.index.keys() : [];
      })
    : new Map<string, string>();
  const unpublished = options.preparedVersions
    ? new AuthoredCitationMap((key) => lookup(key, "unpublished"), () => [])
    : new Map<string, string>();
  // Null-prototype maps: coordinates and collection names come from arbitrary
  // (possibly third-party) specs, so keys like `__proto__` or `constructor`
  // must land as plain own properties, never mutate a prototype.
  const manifest: CoordinatesManifest = { version: 2, collections: Object.create(null) };

  for (const target of resolveAllApiCollections(api, projectMountContext(root))) {
    const prepared = options.preparedVersions?.get(target.versionKey);
    if (prepared && !target.isDefault) {
      historical.set(target.versionKey, { target, source: prepared });
      continue;
    }
    let summary: ApiCitationSummary;
    if (prepared) {
      summary = prepared.read();
    } else {
      const source = await resolveSpecSource(
        {
          collection: target.namespace,
          spec: target.spec,
          label: target.label,
          mountPath: target.mountPath,
          ...targetUrlFields(target),
          requireOperationId: target.requireOperationId,
          schemaPages: target.schemaPages,
          routes: target.routes,
          samples: target.samples,
          extensions: target.extensions,
        },
        root,
      );
      summary = collectApiCitationSummary(
        await buildApiModel(source),
        target.schemaPages ?? false,
      );
    }
    for (const [coordinate, schema] of Object.entries(summary.unpublished)) {
      if (target.version)
        unpublished.set(
          citationKey(target.namespace, target.version, coordinate),
          schema,
        );
      if (target.isDefault)
        unpublished.set(
          citationKey(target.namespace, undefined, coordinate),
          schema,
        );
    }

    const collection =
      manifest.collections[target.namespace] ??
      (manifest.collections[target.namespace] = { defaultVersion: null, pages: [] });
    if (target.isDefault) collection.defaultVersion = target.version;

    const targets = summary.targets.map(({ coordinate, slug, anchor }) => ({
      coordinate,
      url: `${pageUrl(target, slug)}${anchor === undefined ? "" : `#${anchor}`}`,
    }));

    const validTargets = targets.filter(({ url }) => isSafeCitationPath(url));
    const pages = createPageGroups(validTargets);
    if (target.version) {
      (collection.versions ??= Object.create(null))[target.version] = pages;
    }
    if (target.isDefault) collection.pages = pages;

    for (const { coordinate, url } of validTargets) {
      if (target.version) {
        index.set(citationKey(target.namespace, target.version, coordinate), url);
      }
      if (target.isDefault) {
        index.set(citationKey(target.namespace, undefined, coordinate), url);
      }
    }
  }

  // Stable transport bytes independent of declaration ordering.
  manifest.collections = Object.assign(Object.create(null), Object.fromEntries(
    Object.entries(manifest.collections).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0),
  ));
  for (const collection of Object.values(manifest.collections)) {
    if (collection.versions) collection.versions = Object.fromEntries(
      Object.entries(collection.versions).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0),
    );
  }
  return { index, manifest, unpublished };
}

export { ingestRemoteManifest } from "./coordinate-manifest.js";

/**
 * Build-time-only reader for the coordinate-citation index baked into
 * `virtual:nimbus/coordinates`.
 *
 * Kept OUT of `runtime-config.ts` on purpose: that module's whole-namespace
 * dynamic import is pulled by runtime helpers across the framework, which would
 * drag the citation index into the Worker bundle. This loader is imported only by
 * prerendered agent-surface code, so the coordinate blob stays in the build
 * graph. The dynamic import matches the runtime-config house rule (Astro's
 * config loader can't resolve a top-level static `virtual:` import).
 */

import type { CitationIndex } from "./citations.js";
import type { CoordinatesManifest } from "./citation-index.js";

let _cached: CitationIndex | null = null;

export async function loadCitationIndex(): Promise<CitationIndex> {
  if (_cached) return _cached;
  const mod = await import("virtual:nimbus/coordinates");
  const value: CitationIndex = new Map(Object.entries(mod.coordinates ?? {}));
  _cached = value;
  return value;
}

export async function loadCoordinatesManifest(): Promise<CoordinatesManifest> {
  const mod = await import("virtual:nimbus/coordinates");
  return mod.manifest;
}

/** Test-only cache reset. In dev the module itself is invalidated via the Vite
 *  module graph, which discards this singleton on re-execution. */
export function _resetCitationIndexCacheForTests(): void {
  _cached = null;
}

/**
 * The coordinate-citation resolver — the pure, mode-agnostic core.
 *
 * A prose page cites an API operation with a markdown link whose target is a
 * coordinate, not a hand-typed URL:
 *
 *     [create a zone](api.ref:zones:createZone)
 *     [in v1](api.ref:zones@v1:createZone)
 *
 * `resolveCitations` rewrites those link targets to site-absolute URLs against a
 * citation index (coordinate → URL). It never reads the API model, so the same
 * function serves same-app, split-app, and cross-repo citations, at build or
 * request time.
 *
 * Two failure modes over one resolver, chosen by the caller:
 *   - `author`  — a human wrote it. Unknown coordinate → build error.
 *   - `derived` — the reference minted it. Unknown coordinate → `#` + warning.
 *
 * The sentinel is `api.ref:`. The `.` is load-bearing: collection names are
 * `[a-z0-9-]+` (never a dot), so it can never alias a real collection, yet stays
 * URI-scheme-shaped so markdown and the internal-link lint leave it alone.
 */

import { suggest } from "../levenshtein.js";
import { fencedBlocks, INLINE_CODE } from "../code-regions.js";
import { toDocumentHref } from "../url.js";

/** The one prefix that marks a link target as a coordinate citation. */
export const CITATION_SENTINEL = "api.ref:";

/**
 * A citation only counts when it is the target of a link — a markdown
 * `](api.ref:…)` or a JSX `href="api.ref:…"`. A bare `api.ref:` mentioned in
 * prose is not a citation and must never trip resolution or the fail-loud guard.
 *
 * Coordinates are opaque and may contain spaces (a tag-label coordinate like
 * `tags.User Management`) or parentheses. Three alternatives, tried in order:
 *   1. CommonMark angle destination `](<api.ref:…>)` — the standard wrapper for
 *      a target containing spaces/parens. Interior padding is tolerated and the
 *      brackets are dropped on rewrite (a resolved URL never needs them).
 *   2. JSX `href="api.ref:…"` — delimited by its own quote, so spaces inside are
 *      captured; the closing quote is left intact.
 *   3. Bare markdown `](api.ref:…)` — terminated by whitespace, `)`, or a quote.
 *
 * Captured groups: (angle prefix, angle token, href prefix, href token,
 * bare prefix, bare token).
 */
const CITATION_LINK =
  /(\]\(\s*)<\s*(api\.ref:[^>\n]*?)\s*>|(\bhref\s*=\s*["'])(api\.ref:[^"'\n]+)|(\]\(\s*)(api\.ref:[^\s)"']+)/g;

/** A collection name segment: matches the coordinate grammar's rule. */
const COLLECTION = /^[a-z0-9-]+$/;
/** A version id: no `:` or `@`, no leading/trailing/consecutive separators. */
const VERSION = /^[a-z0-9]+(?:[.-][a-z0-9]+)*$/;

export type ResolveMode = "author" | "derived";

export type CitationDiagnosticLevel = "error" | "warning";

export interface CitationDiagnostic {
  level: CitationDiagnosticLevel;
  message: string;
  /** The raw citation token, for pointing the author at the offending link. */
  token: string;
}

/** A parsed citation token (sentinel already stripped). */
export interface ParsedCitation {
  collection: string;
  /** Absent → the family-default version. */
  version?: string;
  coordinate: string;
}

/**
 * The resolution contract: coordinate → site-absolute URL. Keys are formed by
 * `citationKey`; the family-default target is also stored under the unversioned
 * key so an unversioned citation resolves to it.
 */
export interface CitationIndex extends ReadonlyMap<string, string> {
  /** Optional on-demand keys for one historical version, never the full history. */
  keysForVersion?(scope: string): Iterable<string>;
}

/** The lookup key for a parsed citation. Version-bearing when a version is given. */
export function citationKey(collection: string, version: string | undefined, coordinate: string): string {
  return version ? `${collection}@${version}:${coordinate}` : `${collection}:${coordinate}`;
}

/** The response field with the same path as an unknown request body field
 *  (`op.id` → `op.response.201.id`), which is where a readOnly field is
 *  listed. Only searched when a citation already fails. */
function responseFieldFor(key: string, index: CitationIndex, known: ReadonlySet<string>): string | undefined {
  const colon = key.indexOf(":");
  const scope = key.slice(0, colon + 1);
  const coordinate = key.slice(colon + 1);
  const candidates = scope.includes("@")
    ? [...known, ...(index.keysForVersion?.(scope.slice(0, -1)) ?? [])]
    : known;
  for (let dot = coordinate.lastIndexOf("."); dot > 0; dot = coordinate.lastIndexOf(".", dot - 1)) {
    const page = index.get(`${scope}${coordinate.slice(0, dot)}`);
    if (!page || page.includes("#")) continue;
    const prefix = `${scope}${coordinate.slice(0, dot)}.response.`;
    const suffix = coordinate.slice(dot);
    for (const candidate of candidates) {
      if (!candidate.startsWith(prefix) || !candidate.endsWith(suffix)) continue;
      const responsePath = candidate.slice(prefix.length, candidate.length - suffix.length);
      const status = responsePath.split(".")[0];
      if (status && index.has(`${prefix}${status}`)) return candidate;
    }
    return undefined;
  }
  return undefined;
}

/**
 * Parse a full link target into a citation, or `null` when it isn't one.
 * Returns a diagnostic string (never `null`) when the target *starts* with the
 * sentinel but is malformed — an author who typed `api.ref:` meant a citation,
 * so a broken one is an error, not a passthrough.
 */
export function parseCitation(target: string): ParsedCitation | { fault: string } | null {
  if (!target.startsWith(CITATION_SENTINEL)) return null;
  const rest = target.slice(CITATION_SENTINEL.length);

  const firstColon = rest.indexOf(":");
  if (firstColon === -1) {
    return { fault: `"${target}" is missing the ":coordinate" — expected api.ref:<collection>[@<version>]:<coordinate>.` };
  }
  const collectionPart = rest.slice(0, firstColon);
  const coordinate = rest.slice(firstColon + 1);
  if (coordinate === "") {
    return { fault: `"${target}" has an empty coordinate.` };
  }

  let collection = collectionPart;
  let version: string | undefined;
  const at = collectionPart.indexOf("@");
  if (at !== -1) {
    collection = collectionPart.slice(0, at);
    version = collectionPart.slice(at + 1);
    if (collectionPart.indexOf("@", at + 1) !== -1) {
      return { fault: `"${target}" has more than one "@" before the coordinate.` };
    }
    if (!VERSION.test(version)) {
      return { fault: `"${target}" has an invalid version "${version}" (allowed: lowercase alphanumerics separated by "." or "-").` };
    }
  }
  if (!COLLECTION.test(collection)) {
    return { fault: `"${target}" has an invalid collection "${collection}" (allowed: [a-z0-9-]).` };
  }

  return version ? { collection, version, coordinate } : { collection, coordinate };
}

/**
 * True when a citation-index *value* is safe to bake into an href: a single-slash
 * site-absolute path with no scheme (blocks `javascript:`/`data:`) and no
 * protocol-relative `//` (blocks off-origin), no whitespace, backslash, or
 * control characters. Applied on ingest to every value, local and remote, so a
 * hostile or buggy manifest can never inject a dangerous href.
 */
export function isSafeCitationPath(value: string): boolean {
  if (!value.startsWith("/")) return false;
  if (value.startsWith("//")) return false;
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return false;
  if (/[\u0000-\u0020\\]/.test(value)) return false;
  return true;
}

/**
 * Resolve a parsed citation against a citation index, shaped like every other
 * generated page link (Astro's `trailingSlash`). `undefined` when unknown.
 */
export function resolveCitation(parsed: ParsedCitation, citationIndex: CitationIndex): string | undefined {
  const url = citationIndex.get(citationKey(parsed.collection, parsed.version, parsed.coordinate));
  return url === undefined ? undefined : toDocumentHref(url);
}

export interface ResolveCitationsResult {
  code: string;
  diagnostics: CitationDiagnostic[];
}

export interface ResolveCitationsOptions {
  mode: ResolveMode;
  citationIndex: CitationIndex;
  /**
   * Citation keys of schemas (and their fields) that exist but have no page
   * because their collection sets `schemaPages: false` → the schema's name.
   * Author mode fails such a citation with a reason that names the option.
   */
  unpublished?: ReadonlyMap<string, string>;
}

/**
 * True when the source contains at least one citation link. Cheap pre-filter and
 * the signal the fail-loud guard uses: a body with a citation but no citation index
 * is a build error, never a silent passthrough of a raw token.
 */
export function hasCitation(source: string): boolean {
  CITATION_LINK.lastIndex = 0;
  return CITATION_LINK.test(protectCode(source).code);
}

/**
 * Rewrite every coordinate-citation link target in a markdown/MDX source string
 * to its resolved URL. Operates on markdown link syntax `](api.ref:…)` and JSX
 * `href="api.ref:…"`. Code (fenced + inline) is protected first, so documented
 * syntax inside a code span is never rewritten or reported.
 *
 * Unknown handling follows `mode`. Malformed tokens are always errors. The
 * function is pure: it collects diagnostics; the caller decides whether an
 * `error` diagnostic fails the build.
 */
export function resolveCitations(source: string, options: ResolveCitationsOptions): ResolveCitationsResult {
  const { mode, citationIndex, unpublished } = options;
  const diagnostics: CitationDiagnostic[] = [];
  const known = new Set(citationIndex.keys());
  // An unknown coordinate in a known collection fails an author build; a
  // citation to an unknown collection degrades to "#" + a warning.
  const knownCollections = new Set<string>();
  for (const key of known) {
    const at = key.indexOf("@");
    const colon = key.indexOf(":");
    const end = at === -1 ? colon : Math.min(at, colon);
    if (end > 0) knownCollections.add(key.slice(0, end));
  }

  const { code: guarded, restore } = protectCode(source);

  CITATION_LINK.lastIndex = 0;
  const rewritten = guarded.replace(
    CITATION_LINK,
    (
      _whole: string,
      anglePrefix: string | undefined,
      angleToken: string | undefined,
      hrefPrefix: string | undefined,
      hrefToken: string | undefined,
      barePrefix: string | undefined,
      bareToken: string | undefined,
    ) => {
      if (angleToken !== undefined) return `${anglePrefix}${rewriteToken(angleToken)}`;
      if (hrefToken !== undefined) return `${hrefPrefix}${rewriteToken(hrefToken)}`;
      return `${barePrefix}${rewriteToken(bareToken as string)}`;
    },
  );

  function rewriteToken(token: string): string {
    const parsed = parseCitation(token);
    if (parsed === null) return token;
    if ("fault" in parsed) {
      diagnostics.push({ level: "error", message: parsed.fault, token });
      return "#";
    }
    const url = resolveCitation(parsed, citationIndex);
    if (url !== undefined) return url;

    const key = citationKey(parsed.collection, parsed.version, parsed.coordinate);
    const schema = mode === "author" ? unpublished?.get(key) : undefined;
    if (schema !== undefined) {
      const target =
        parsed.coordinate === schema ? `"${schema}" is a schema` : `"${parsed.coordinate}" is a field of schema "${schema}"`;
      diagnostics.push({
        level: "error",
        message:
          `Citation "${token}" has no page to link to: ${target}, and schema pages are off for "${parsed.collection}" ` +
          `(\`schemaPages: false\`). Cite an operation that uses it, or set \`schemaPages: true\`.`,
        token,
      });
      return "#";
    }
    const response = mode === "author" ? responseFieldFor(key, citationIndex, known) : undefined;
    const hint = response ?? suggest(key, known, 4);
    const detail = response
      ? ` Request field lists leave out readOnly fields; if it is readOnly, cite it under the response: "${CITATION_SENTINEL}${response}".`
      : hint ? ` Did you mean "${CITATION_SENTINEL}${hint}"?` : "";
    const authoritative = knownCollections.has(parsed.collection);
    if (mode === "author" && authoritative) {
      diagnostics.push({
        level: "error",
        message: `Citation "${token}" does not resolve to any API page in "${parsed.collection}".${detail} A renamed or removed operation fails the build.`,
        token,
      });
    } else if (authoritative) {
      diagnostics.push({
        level: "warning",
        message: `Citation "${token}" does not resolve; rendering "#".${detail}`,
        token,
      });
    } else {
      diagnostics.push({
        level: "warning",
        message: `Citation "${token}" targets unknown collection "${parsed.collection}"; rendering "#". If it is a remote reference, check its manifest is declared and reachable.`,
        token,
      });
    }
    return "#";
  }

  return { code: restore(rewritten), diagnostics };
}

/** Replace fenced + inline code with placeholders so citations inside code are left alone. */
function protectCode(source: string): { code: string; restore: (value: string) => string } {
  const chunks: string[] = [];
  const PREFIX = "\x00NIMBUS_CITE_CODE_";
  const SUFFIX = "\x00";
  const lines = source.split("\n");
  const out: string[] = [];
  let next = 0;
  for (const { open, close } of fencedBlocks(lines)) {
    out.push(...lines.slice(next, open), store(lines.slice(open, close + 1).join("\n")));
    next = close + 1;
  }
  out.push(...lines.slice(next));
  const code = out.join("\n").replace(INLINE_CODE, store);
  function store(match: string): string {
    const index = chunks.length;
    chunks.push(match);
    return `${PREFIX}${index}${SUFFIX}`;
  }
  return {
    code,
    restore(value: string): string {
      return value.replace(new RegExp(`${PREFIX}(\\d+)${SUFFIX}`, "g"), (_m, i) => chunks[Number(i)] ?? "");
    },
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import {
  ADAPTER_IDS,
  ADAPTER_RECIPES,
  applyAdapterToConfig,
  alreadyWiredAdapterId,
  isCommonJsConfig,
} from "../src/_internal/adapters.js";

const STARTER_CONFIG = `import { defineConfig } from "astro/config";
import icon from "astro-icon";
import nimbus, { defineConfig as defineNimbusConfig } from "@cloudflare/nimbus-docs";

const nimbusConfig = defineNimbusConfig({
  site: "https://example.com",
  title: "Nimbus",
});

export default defineConfig({
  // nimbus:adapter
  output: "static",
  integrations: [icon(), nimbus(nimbusConfig)],
});
`;

test("flips output and wires each adapter at the marker", () => {
  for (const id of ADAPTER_IDS) {
    const res = applyAdapterToConfig(STARTER_CONFIG, id);
    assert.equal(res.status, "applied", `${id} should apply`);
    if (res.status !== "applied") return;
    const recipe = ADAPTER_RECIPES[id];
    assert.match(res.source, /output:\s*"server"/, `${id} flips output`);
    assert.ok(!/output:\s*"static"/.test(res.source), `${id} removes static`);
    assert.ok(res.source.includes(recipe.importStatement), `${id} adds import`);
    assert.ok(
      res.source.includes(`adapter: ${recipe.adapterExpression},`),
      `${id} adds adapter field`,
    );
    if (id === "cloudflare") {
      assert.match(res.source, /rendering:\s*\{\s*default:\s*"request"/);
    } else {
      assert.doesNotMatch(res.source, /default:\s*"request"/);
    }
    // The adapter field lands directly after the output line.
    assert.match(
      res.source,
      new RegExp(
        `output:\\s*"server",\\n\\s*adapter: ${recipe.adapterExpression.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")},`,
      ),
      `${id} places adapter after output`,
    );
  }
});

