<a href="/docs/first" href="/second">Duplicate</a>
</div>`,
  );
  assert.equal(
    normalizeAuthoredLinks(
      `Prefix <script>const example = '<a href="/unchanged">'</script>

<div>
<template><a href="/template">Template</a></template>
<area href="/map" />
</div>`,
      { base: "/docs", sourceId: "generated.md" },
    ),
