test("normalization preserves unrelated source across format, nesting, Unicode and line endings", () => {
  for (const format of ["md", "mdx"] as const) {
    for (const newline of ["\n", "\r\n"]) {
      for (const prefix of ["", "😀 文档\n\n"]) {
        for (const wrapper of format === "md"
          ? ["plain", "quote", "list"]
          : ["plain", "quote", "list", "component"]) {
          const link =
            format === "md"
              ? '<a\nHREF = "&sol;html">HTML</a>'
              : '<Card href={"/html"}>HTML</Card>';
          const body = [
            format === "md"
              ? "<!-- generated {comment} -->"
              : "{/* comment */}",
            "",
            "[Guide](/guide?x=1#top)",
            "",
            link,
            "",
            "<code>www.example.org</code>",
            "",
            '<template>\n<a href="/template">Template</a>\n</template>',
            "",
            "```tsx",
            '<a href="/literal">example</a>',
            "const value = <Unclosed>;",
            "```",
            "",
            "`[Inline](/literal)`",
          ].join("\n");
          const wrap = (text: string) =>
            wrapper === "quote"
              ? text
                  .split("\n")
                  .map((line) => `> ${line}`)
                  .join("\n")
              : wrapper === "list"
                ? `1. Item\n\n${text
                    .split("\n")
                    .map((line) => `   ${line}`)
                    .join("\n")}`
                : wrapper === "component" && format === "mdx"
                  ? `<Card href="/outer">\n\n${text}\n\n</Card>`
                  : text;
          const source = (prefix + wrap(body)).replaceAll("\n", newline);
          const expected = source
            .replace("[Guide](/guide?x=1#top)", "[Guide](/docs/guide?x=1#top)")
            .replace('HREF = "&sol;html"', 'HREF = "/docs&sol;html"')
            .replace('href={"/html"}', 'href={"/docs/html"}')
            .replace('href="/outer"', 'href="/docs/outer"')
            .replace('href="/template"', 'href="/docs/template"');
          const sourceId = `docs:fixture.${format}`;
          const label = JSON.stringify({ format, newline, prefix, wrapper });
          assert.equal(
            normalizeAuthoredLinks(source, { base: "/", sourceId }),
            source,
            label,
          );
          assert.equal(
            normalizeAuthoredLinks(source, { base: "/docs", sourceId }),
            expected,
            label,
          );
        }
      }
    }
  }
  for (const href of [
    '"/../escape"',
    '"&sol;../escape"',
    "'/safe/%2fescape'",
  ]) {
    for (const source of [
      `<a href=${href}>Link</a>`,
      `> <a\n> href=${href}>Link</a>`,
    ]) {
      assert.throws(
        () =>
          normalizeAuthoredLinks(source, { base: "/", format: "markdown" }),
        /destination escapes its canonical path/,
      );
    }
  }
});

import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { test } from "node:test";

import { checkAuthoring } from "../../src/check/authoring.js";
import { _resetLinkEnvCacheForTests as _resetInternalLinkCacheForTests } from "../../src/lint/link-env.js";
import { ROUTE_TRUTH_VERSION } from "../../src/lint/site-model.js";

interface ProjectOpts {
  body?: string;
  lintJson?: Record<string, unknown>;
  routesJson?: Record<string, unknown>;
}

function project(opts: ProjectOpts = {}): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nimbus-authoring-"));
  const docs = path.join(dir, "src", "content", "docs");
  fs.mkdirSync(docs, { recursive: true });
  fs.writeFileSync(
    path.join(docs, "page.mdx"),
    `---\ntitle: Page\n---\n\n${opts.body ?? "See [x](/nope-broken)."}\n`,
  );
  if (opts.lintJson || opts.routesJson) {
    fs.mkdirSync(path.join(dir, ".nimbus"), { recursive: true });
  }
  if (opts.lintJson) {
    fs.writeFileSync(
      path.join(dir, ".nimbus", "lint.json"),
      JSON.stringify({ version: 1, ...opts.lintJson }),
    );
  }
  if (opts.routesJson) {
    fs.writeFileSync(
      path.join(dir, ".nimbus", "routes.json"),
      JSON.stringify({ version: ROUTE_TRUTH_VERSION, ...opts.routesJson }),
    );
  }
  return dir;
}

const INTERNAL_LINK_ON = {
  rules: { "nimbus/internal-link": "error" },
  collections: {},
  site: "https://docs.example.com",
};

const INTERNAL_LINK_ON_COLLECTION = {
  rules: {},
  collections: { docs: { rules: { "nimbus/internal-link": "error" } } },
  site: "https://docs.example.com",
};

const hasFinding = (r: { findings: { code: string }[] }, code: string) =>
  r.findings.some((f) => f.code === code);
const note = (r: { notes: { code: string }[] }, code: string) =>
  r.notes.find((n) => n.code === code);

test("no .nimbus → authoring-optin-skipped note, evaluated true, never in findings (renamed code)", () => {
  _resetInternalLinkCacheForTests();
  const dir = project();
  try {
    const r = checkAuthoring(dir);
    assert.equal(r.scope, "authoring");
    assert.equal(r.evaluated, true, "core rules ran — the scope is evaluated");
    const skip = note(r, "nimbus/authoring-optin-skipped");
    assert.ok(skip, "opt-in skip is surfaced as a note");
    assert.equal(skip.requiresBuild, true);
    assert.ok(!hasFinding(r, "nimbus/authoring-optin-skipped"), "never a finding");
    assert.ok(!hasFinding(r, "nimbus/authoring-not-evaluated"), "old code is gone");
    assert.ok(!hasFinding(r, "nimbus/internal-link"));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("lint.json enables internal-link but no routes.json → internal-link-skipped note (not a false pass)", () => {
  _resetInternalLinkCacheForTests();
  const dir = project({ lintJson: INTERNAL_LINK_ON });
  try {
    const r = checkAuthoring(dir);
    const skipped = note(r, "nimbus/internal-link-skipped");
    assert.ok(skipped, "link checking skip is a note");
    assert.equal(skipped.requiresBuild, true);
    assert.ok(!hasFinding(r, "nimbus/internal-link-skipped"));
    assert.ok(!hasFinding(r, "nimbus/internal-link"));
    assert.ok(!note(r, "nimbus/authoring-optin-skipped"), "opt-in ran, so no opt-in note");
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("lint.json + routes.json present → broken link is actually caught", () => {
  _resetInternalLinkCacheForTests();
  const dir = project({
    lintJson: INTERNAL_LINK_ON,
    routesJson: { base: "/", knownRoutes: ["/"], redirects: [], redirectPages: [], redirectRules: "cloudflare", opaqueNamespaces: [] },
  });
  try {
    const r = checkAuthoring(dir);
    const broken = r.findings.find((f) => f.code === "nimbus/internal-link");
    assert.ok(broken, "the broken link must be flagged when route truth exists");
    assert.equal(broken.severity, "error");
    assert.ok(!note(r, "nimbus/internal-link-skipped"));
    assert.ok(!note(r, "nimbus/authoring-optin-skipped"));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

